function slugify(text) {
  return String(text || '')
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function escapeHtml(value = '') {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'
  }[char]));
}

function safeUrl(value = '', fallback = '') {
  const raw = String(value || '').trim();
  if (!raw) return fallback;
  if (/^(https?:\/\/|mailto:|tel:|\/|\.\.?\/)/i.test(raw)) return raw;
  return fallback;
}

function sanitizeRichHtml(html = '') {
  const template = document.createElement('template');
  template.innerHTML = String(html || '');
  const allowedTags = new Set(['P','BR','STRONG','B','EM','I','U','H2','H3','H4','UL','OL','LI','BLOCKQUOTE','A','CODE','PRE','HR','TABLE','THEAD','TBODY','TR','TH','TD','FIGURE','FIGCAPTION','IMG']);
  const allowedAttrs = {
    A: new Set(['href','title','target','rel']),
    IMG: new Set(['src','alt','title','width','height','loading']),
    TH: new Set(['colspan','rowspan','scope']),
    TD: new Set(['colspan','rowspan'])
  };
  [...template.content.querySelectorAll('*')].forEach((node) => {
    if (!allowedTags.has(node.tagName)) {
      node.replaceWith(...node.childNodes);
      return;
    }
    [...node.attributes].forEach((attr) => {
      if (!allowedAttrs[node.tagName]?.has(attr.name.toLowerCase())) node.removeAttribute(attr.name);
    });
    if (node.tagName === 'A') {
      const href = node.getAttribute('href') || '';
      if (!/^(https?:\/\/|mailto:|tel:|\/|#)/i.test(href)) node.removeAttribute('href');
      if (node.getAttribute('target') === '_blank') node.setAttribute('rel', 'noopener noreferrer');
    }
    if (node.tagName === 'IMG') {
      const src = node.getAttribute('src') || '';
      if (!/^(https?:\/\/|\/|\.\.?\/)/i.test(src)) node.remove();
      else if (!node.getAttribute('loading')) node.setAttribute('loading', 'lazy');
    }
  });
  return template.innerHTML;
}

function sanitizeArticleContent(html = '') {
  return sanitizeRichHtml(html)
    .replace(/<figure\b[^>]*>[\s\S]*?<img\b[^>]*>[\s\S]*?<\/figure>/gi, '')
    .replace(/<img\b[^>]*>/gi, '')
    .replace(/\/insights\/a-practical-guide-to-entering-the-saudi-market/g, '/insights/company-formation-in-saudi-arabia');
}

const INITIAL_SCRIPT_HREF = document.currentScript?.src || location.href;
const APP_BASE_URL = new URL('.', INITIAL_SCRIPT_HREF);
const SITE_BASE_PATH = APP_BASE_URL.pathname.replace(/\/+$/, '');
const apiUrl = (path) => new URL(String(path).replace(/^\/+/, ''), APP_BASE_URL).toString();

let csrfTokenPromise = null;
async function getCsrfToken() {
  if (!csrfTokenPromise) {
    csrfTokenPromise = fetch(apiUrl('api/auth/csrf.php'), { credentials: 'same-origin', headers: { Accept: 'application/json' } })
      .then(async (response) => {
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.csrf_token) throw new Error(data.error || 'Unable to initialize secure form submission.');
        return data.csrf_token;
      })
      .catch((error) => { csrfTokenPromise = null; throw error; });
  }
  return csrfTokenPromise;
}

async function submitInquiry(payload) {
  const token = await getCsrfToken();
  const response = await fetch(apiUrl('api/inquiries.php'), {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token, Accept: 'application/json' },
    body: JSON.stringify(payload)
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 419) csrfTokenPromise = null;
    throw new Error(data.error || 'We could not submit your request. Please try again.');
  }
  return data;
}

function cleanPath(href) {
  if (!href) return '/';
  let path = href.replace(/#.*$/, '').trim();
  if (!path || path === 'home' || path === '/home') return '/';
  if (/\.[a-z0-9]+$/i.test(path) || path.startsWith('http:') || path.startsWith('https:') || path.startsWith('mailto:') || path.startsWith('tel:')) return path;
  if (SITE_BASE_PATH && (path === SITE_BASE_PATH || path.startsWith(`${SITE_BASE_PATH}/`))) {
    path = path.slice(SITE_BASE_PATH.length) || '/';
  }
  if (!path.startsWith('/')) path = '/' + path;
  return path;
}

function toHref(page) {
  if (/\.[a-z0-9]+$/i.test(page)) return page;
  const path = page === 'home' ? '/' : `/${page}`;
  return `${SITE_BASE_PATH}${path}` || path;
}

function routeInfo() {
  const recognizedPages = ['home', 'about', 'services', 'insights', 'blog', 'contact', 'privacy-policy', 'terms-and-conditions', 'conversation', 'visa-assistance', 'automation', 'advisory-session', 'advisors'];

  if (location.hash) {
    const rawHash = location.hash.replace(/^#\/?/, '').split('?')[0].trim();
    if (rawHash.startsWith('insights/')) {
      return { view: 'article', slug: rawHash.slice('insights/'.length) };
    }
    if (rawHash.startsWith('blog/')) {
      return { view: 'article', slug: rawHash.slice('blog/'.length) };
    }
    if (recognizedPages.includes(rawHash) && rawHash !== 'home') {
      return { view: rawHash, slug: '' };
    }
  }

  let pathname = location.pathname;
  if (SITE_BASE_PATH && (pathname === SITE_BASE_PATH || pathname.startsWith(`${SITE_BASE_PATH}/`))) {
    pathname = pathname.slice(SITE_BASE_PATH.length) || '/';
  }
  const segment = pathname.replace(/^\/+/, '').replace(/\/+$/, '').replace(/\.html$/, '').trim();
  if (!segment || segment === 'home' || segment === 'index') return { view: 'home', slug: '' };
  if (segment === 'insights' || segment === 'blog') return { view: 'insights', slug: '' };
  if (segment.startsWith('insights/')) {
    return { view: 'article', slug: segment.slice('insights/'.length) };
  }
  if (segment.startsWith('blog/')) {
    return { view: 'article', slug: segment.slice('blog/'.length) };
  }
  if (segment.startsWith('article/')) {
    return { view: 'article', slug: segment.slice('article/'.length) };
  }
  if (recognizedPages.includes(segment)) {
    return { view: segment, slug: '' };
  }

  return { view: '404', slug: '' };
}

function route() {
  return routeInfo().view;
}

function link(page, label) {
  return `<a href="${toHref(page)}">${label}</a>`;
}

function scrollToTop() {
  const root = document.documentElement;
  const previousBehavior = root.style.scrollBehavior;
  root.style.scrollBehavior = 'auto';
  window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  root.style.scrollBehavior = previousBehavior;
}

function scrollToHashTarget(hash) {
  const decodedHash = decodeURIComponent(String(hash || '').replace(/^#/, ''));
  if (!decodedHash) return false;
  const targetEl = document.getElementById(decodedHash) || document.getElementById(`service-${decodedHash}`);
  if (!targetEl) return false;
  const root = document.documentElement;
  const previousBehavior = root.style.scrollBehavior;
  root.style.scrollBehavior = 'auto';
  window.scrollTo({ top: targetEl.getBoundingClientRect().top + window.scrollY, left: 0, behavior: 'auto' });
  root.style.scrollBehavior = previousBehavior;
  return true;
}

function applyPendingRouteScroll() {
  if (pendingRouteScroll !== `${location.pathname}${location.hash}`) return;
  if (!location.hash || !scrollToHashTarget(location.hash)) scrollToTop();
}

function navigate(path) {
  const [pathName, hash] = String(path || '/').split('#', 2);
  const targetPath = `${SITE_BASE_PATH}${pathName}` || pathName;
  const target = hash ? `${targetPath}#${hash}` : targetPath;
  if (`${location.pathname}${location.hash}` === target) return;
  history.pushState(null, '', target);
  pendingRouteScroll = target;
  renderSite();
  requestAnimationFrame(applyPendingRouteScroll);
  setTimeout(() => {
    applyPendingRouteScroll();
    if (pendingRouteScroll === `${location.pathname}${location.hash}`) pendingRouteScroll = null;
  }, 800);
}

function isPrivateNavigationItem(item) {
  const href = String(item?.href || '').toLowerCase();
  const label = String(item?.label || '').toLowerCase();
  return href === '/login.php' || href === '/login' || href.endsWith('/login.php') || href.endsWith('/login') || label.includes('cms sign in');
}

